    // Whole words only, so "Hubert" is not Uber.
    private val words: List<Pair<Regex, String>> = listOf(
        "uber", "amazon", "swiggy", "zomato", "netflix", "flipkart", "starbucks", "spotify",
    ).map { Regex("""\b$it\b""", RegexOption.IGNORE_CASE) to it } + (Regex("""\bbig\s?basket\b""", RegexOption.IGNORE_CASE) to "bigbasket")

    /** The key of the brand a payee name is, or null. */
    fun forName(name: String): String? = words.firstOrNull { it.first.containsMatchIn(name) }?.second
}

@Composable internal fun BrandTile(key: String, size: Dp) {
    val logo = BrandLogos.all[key] ?: return
    val path = remember(key) { PathParser().parsePathString(logo.path).toPath() }
    Box(Modifier.size(size).clip(CircleShape).background(Color(logo.bg)), contentAlignment = Alignment.Center) {
        Canvas(Modifier.size(size * 0.58f)) {
            scale(this.size.minDimension / 24f, Offset.Zero) { drawPath(path, Color(logo.fg)) }
        }
    }
}
